// i18next初始化
document.addEventListener('DOMContentLoaded', function () {
    // 初始化i18next
    i18next
        .use(i18nextHttpBackend)
        .use(i18nextBrowserLanguageDetector)
        .init({
            supportedLngs: ['zh', 'en', 'pt'],
            // resources : Ta,
            fallbackLng: 'en',
            debug: true,
            ns: ['translation', 'common'],
            defaultNS: 'translation',
            backend: {
                loadPath: 'locales/{{lng}}/common.json?v=ba8d06ec'
            },
            interpolation: {
                escapeValue: !1
            },
            detection: {
                order: ['querystring', 'localStorage', 'navigator'],
                lookupQuerystring: 'lng',
                lookupLocalStorage: 'i18nextLng',
                caches: ['localStorage']
            }
        }
            , function (err, t) {
                // 初始化完成后更新所有文本
                updateContent();
                setHtmlLang(i18next.language);
                i18next.on('languageChanged', setHtmlLang);

                // 添加语言切换器
                addLanguageSwitcher();
            });
    i18next.addResourceBundle('en', 'translation', Wa.en.translation);
    i18next.addResourceBundle('zh', 'translation', Wa.zh.translation);
    i18next.addResourceBundle('pt', 'translation', Pa);

    // The page's lang attribute follows the shown language (the game's pt bundle is Brazilian Portuguese).
    function setHtmlLang(lng) {
        document.documentElement.lang = lng === 'pt' ? 'pt-BR' : (lng || 'en');
    }

    // 更新页面内容
    function updateContent() {
        // 更新标题
        document.title = i18next.t('common:title');

        // 更新所有带有data-i18n属性的元素
        document.querySelectorAll('[data-i18n]').forEach(function (element) {
            const key = element.getAttribute('data-i18n');
            if (key) {
                element.textContent = i18next.t(key);
            }
        });

        // 更新所有带有data-i18n-placeholder属性的元素
        document.querySelectorAll('[data-i18n-placeholder]').forEach(function (element) {
            const key = element.getAttribute('data-i18n-placeholder');
            if (key) {
                element.placeholder = i18next.t(key);
            }
        });

        // 更新所有带有data-i18n-option属性的选项
        document.querySelectorAll('option[data-i18n]').forEach(function (element) {
            const key = element.getAttribute('data-i18n');
            if (key) {
                element.textContent = i18next.t(key);
            }
        });
    }

    // 添加语言切换器
    function addLanguageSwitcher() {
        const switcherContainer = document.createElement('div');
        switcherContainer.className = 'language-switcher';
        // The page's top-right bar (index.html) holds the toggles; the buttons go after them.
        const topRightControls = document.getElementById('topRightControls');
        if (!topRightControls) {
            switcherContainer.style.position = 'fixed';
            switcherContainer.style.top = '10px';
            switcherContainer.style.right = '10px';
            switcherContainer.style.zIndex = '1000';
        }

        const languages = [['en', "English"], ['zh', "中文"], ['pt', "Portugu\u00eas"]];
        const buttons = languages.map(function ([lng, text]) {
            const button = document.createElement('button');
            button.className = 'btn btn-sm ' + (i18next.language === lng ? 'btn-primary' : 'btn-outline-primary');
            button.textContent = text;
            button.onclick = function () {
                i18next.changeLanguage(lng).then(updateContent);
                buttons.forEach(function (other) {
                    other.className = 'btn btn-sm ' + (other === button ? 'btn-primary' : 'btn-outline-primary');
                });
            };
            return button;
        });

        buttons.forEach(function (button, index) {
            if (index > 0) switcherContainer.appendChild(document.createTextNode(' '));
            switcherContainer.appendChild(button);
        });

        (topRightControls ?? document.body).appendChild(switcherContainer);
    }
});
